// Read Exoo red edge list on stdin. Delete two vertices; exhaust three-vertex rebuilds.
use std::io::{self,Read};
fn main(){let mut input=String::new();io::stdin().read_to_string(&mut input).unwrap();let v:Vec<usize>=input.split_whitespace().map(|s|s.parse().unwrap()).collect();let mut adj=[0u64;39];for p in v.chunks_exact(2){adj[p[0]]|=1<<p[1];adj[p[1]]|=1<<p[0];}let mut sets=vec![0u64];for (j,r) in adj.iter().enumerate(){let old=sets.len();for i in 0..old{if sets[i]&r==0{sets.push(sets[i]|1<<j);}}}assert_eq!(sets.iter().map(|m|m.count_ones()).max(),Some(9));assert!(adj.iter().all(|s|sets.contains(s)));
let layers:Vec<Vec<u64>>=(7..=9).map(|k|sets.iter().copied().filter(|m|m.count_ones()==k).collect()).collect();let(mut cores,mut maxopts,mut trials,mut solutions)=(0,0,0u64,0u64);
for a in 0..39{for b in a+1..39{let del=(1u64<<a)|(1u64<<b);let nine:Vec<_>=layers[2].iter().copied().filter(|m|m&del==0).collect();let opts:Vec<_>=sets.iter().copied().filter(|s|s&del==0 && nine.iter().all(|m|m&s!=0)).collect();assert!(opts.contains(&(adj[a]&!del)) && opts.contains(&(adj[b]&!del)));maxopts=maxopts.max(opts.len());cores+=1;
let mut pairs=vec![vec![0u8;opts.len()];opts.len()];for(i,&x)in opts.iter().enumerate(){for(j,&y)in opts[..=i].iter().enumerate(){let red=x&y==0;let blue=layers[1].iter().all(|m|m&(del|x|y)!=0);let mask=(blue as u8)|((red as u8)<<1);pairs[i][j]=mask;pairs[j][i]=mask;}}
let ia=opts.iter().position(|&s|s==adj[a]&!del).unwrap();let ib=opts.iter().position(|&s|s==adj[b]&!del).unwrap();assert_ne!(pairs[ia][ib]&(1<<((adj[a]>>b)&1)),0);
for(i,&x)in opts.iter().enumerate(){for(j,&y)in opts[..=i].iter().enumerate(){if pairs[i][j]==0{continue}for(k,&z)in opts[..=j].iter().enumerate(){let p=[pairs[i][j],pairs[i][k],pairs[j][k]];if p.contains(&0){continue}trials+=1;for t in 0..7{if (0..3).any(|l|p[l]&(1<<((t>>l)&1))==0){continue}if t==0 && layers[0].iter().any(|m|m&(del|x|y|z)==0){continue}solutions+=1;println!("solution {a} {b} {x} {y} {z} {t}");}}}}
}}println!("cores={cores} largest_border_pool={maxopts} pairwise_compatible_triples={trials} legal_rebuilds={solutions}");}
